-- PHASE A — ORGANIZATIONAL CLOSURE. Generated by scripts/phase_a/generate_migration.mjs from
-- QuotesDone_PHASE_A_COMPLETE_ORGANIZATION_PACKAGE_PRODUCTION_DIRECT_v2026.08.15 (all 15 files
-- verified against SHA256SUMS.txt before generation).
--
-- ORGANIZATIONAL DESIGN ONLY. This file does not touch knowledge, tools, prompts, model policy,
-- routes, cron, billing, dispatch or autonomy, and it makes no model call of any kind.
--
-- THE WHOLE FILE IS ONE TRANSACTION. PostgreSQL wraps a multi-statement simple query in a single
-- implicit transaction, so any assertion below that raises takes every change with it. That is
-- also what makes the rehearsal honest: the same bytes are sent with a trailing raise, and the
-- organisation fingerprint has to come back unchanged.
--
-- WHAT PRODUCTION ALREADY MATCHED, measured read-only before this was written: 10 active
-- departments, 90 accountable roles, 86 category overlays, 86 org_category_identity rows, 0
-- reporting cycles, 0 self-management. Phase A is not a rebuild. Four roles differ, plus the
-- registries the invariants require and the database had no column or table for.
--
-- ROLLBACK: scripts/sql/phase_a_rollback.sql — retirements are reversed by status, not by
-- re-creation, because nothing here deletes a historical row.

-- TIMEOUTS FIRST, BECAUSE THE ALTERS BELOW TAKE AN ACCESS EXCLUSIVE LOCK. Caught by the
-- migration linter in CI, and it was right: org_role is read by every context assembly in the
-- company, so an ALTER that waits behind a long transaction blocks reads, writes and schema
-- changes for as long as it waits. With a lock_timeout the migration fails fast and rolls back
-- whole rather than holding the hottest table in the estate.
set lock_timeout = '5s';
set statement_timeout = '60s';

-- ============================================================================================
-- PRECONDITIONS. Exact expected baseline. A mismatch means this file is being applied to an
-- organisation that is not the one it was generated against, and it must not proceed.
-- ============================================================================================
do $$
declare v_depts int; v_roles int; v_overlays int; v_cats int; v_cycles int; v_missing text;
begin
  select count(*) into v_depts from public.org_departments where active;
  select count(*) into v_roles from public.org_role where status='active' and runtime_mode <> 'knowledge_overlay';
  select count(*) into v_overlays from public.org_role where status='active' and runtime_mode = 'knowledge_overlay';
  select count(*) into v_cats from public.org_category_identity;
  if v_depts <> 10 then raise exception 'PRECONDITION: expected 10 active departments, found %', v_depts; end if;
  if v_roles <> 90 then raise exception 'PRECONDITION: expected 90 accountable roles, found %', v_roles; end if;
  if v_overlays <> 87 then raise exception 'PRECONDITION: expected 87 active overlay roles (86 category + tax_overlay_uae), found %', v_overlays; end if;
  if v_cats <> 86 then raise exception 'PRECONDITION: expected 86 org_category_identity rows, found %', v_cats; end if;
  -- the four roles this file changes must be present, active, and where the baseline said.
  select string_agg(x, ', ') into v_missing from (
    select 'chief_performance_officer' x where not exists (select 1 from public.org_role where role_id='chief_performance_officer' and status='active' and primary_department_id='exec')
    union all select 'government_relations' where not exists (select 1 from public.org_role where role_id='government_relations' and status='active' and primary_department_id='growth')
    union all select 'partnerships' where not exists (select 1 from public.org_role where role_id='partnerships' and status='active' and primary_department_id='growth')
    union all select 'model_evaluator' where not exists (select 1 from public.org_role where role_id='model_evaluator' and status='active' and primary_department_id='product_eng')
    union all select 'tax_overlay_uae' where not exists (select 1 from public.org_role where role_id='tax_overlay_uae' and status='active')
  ) s;
  if v_missing is not null then raise exception 'PRECONDITION: not in the expected baseline state: %', v_missing; end if;
  if exists (select 1 from public.org_role where role_id in ('corporate_performance_director','strategic_partnerships_government_relations_manager','product_ux_designer'))
    then raise exception 'PRECONDITION: a Phase A target role already exists — this file has already been applied'; end if;
end $$;

-- ============================================================================================
-- SCHEMA. Additive only, and both objects exist because an invariant needs them and the
-- database had nowhere to record the answer.
-- ============================================================================================

-- "every role has a necessity status and explicit reason". org_role had neither column, so the
-- invariant could not be evaluated at all — it was not passing, it was unmeasurable.
alter table public.org_role add column if not exists necessity_status text;
alter table public.org_role add column if not exists necessity_reason text;
comment on column public.org_role.necessity_status is 'Phase A: why this role exists at all — REQUIRED_MANAGER, REQUIRED_CORE, REQUIRED_ON_DEMAND or REQUIRED_REVIEWER. A role that cannot state one is a role nobody has justified.';

-- "every core workflow step has exactly one accountable owner" and "contributors do not become
-- co-accountable owners". workflow_step models the 19 RUNTIME workflows as ordered steps, which
-- is a different subject: it says who acts at step 4, not who is accountable for the workflow.
-- This is the accountability register for the 30 ORGANIZATIONAL workflows, and the primary key
-- is what makes "exactly one owner" true by construction rather than by a check that has to run.
create table if not exists public.org_workflow_ownership (
  workflow_id            text primary key,
  workflow_name          text not null,
  accountable_role_id    text not null references public.org_role(role_id),
  contributors           text[] not null default '{}',
  independent_reviewer   text,
  start_event            text not null,
  required_end_state     text not null,
  founder_boundary       text,
  created_at             timestamptz not null default now(),
  -- the accountable owner may never be their own independent reviewer or challenger. This is the
  -- same rule artifact_review enforces for artifacts, at the level of the workflow itself.
  constraint org_workflow_ownership_reviewer_is_independent_ck
    check (independent_reviewer is null or independent_reviewer <> accountable_role_id)
);
comment on table public.org_workflow_ownership is 'Phase A: the 30 organizational workflows and the single role accountable for each. Contributors are recorded and are deliberately NOT owners.';
alter table public.org_workflow_ownership enable row level security;
revoke all on public.org_workflow_ownership from anon, authenticated;

-- A FIFTH COMMITTEE SEAT, because the package needs one the vocabulary did not have. The seat
-- check allowed chair, member, observer and secretary. The Phase A registry seats the Corporate
-- Performance Director and the Strategy Director as STANDING ADVISERS, which is neither of the
-- two it would otherwise collapse into: a member carries the decision, an observer only watches,
-- and an adviser is expected to speak and is not counted in the decision. Mapping it onto
-- 'observer' would have been the quiet kind of wrong — the migration would have passed and the
-- committee's composition would have said something the package did not.
-- Found by the aborted rehearsal, at 23514, with nothing applied.
-- NOT VALID then VALIDATE, also from the linter: adding a CHECK outright scans the table and
-- blocks writes for the scan. NOT VALID takes the constraint immediately for new rows, and
-- VALIDATE then re-reads the existing ones under a lock that does not block readers or writers.
-- The end state is identical; only the window during which the table is held differs.
-- 27 OCT 2026 (it_engineer, #1595): squawk-cli 2.70 added ban-drop-constraint and flags the next
-- line; 2.66 passed this file with 0 issues. The drop is not a lost guarantee: the same constraint
-- is re-added by the very next statement, stricter. Comment-only change; this migration is applied.
-- squawk-ignore ban-drop-constraint
alter table public.org_role_committee drop constraint if exists org_role_committee_seat_ck;
alter table public.org_role_committee add constraint org_role_committee_seat_ck
  check (seat = any (array['chair','member','observer','secretary','standing_adviser'])) not valid;
alter table public.org_role_committee validate constraint org_role_committee_seat_ck;

-- ============================================================================================
-- CHANGE 1 of 6 — RENAME. Chief Performance Officer -> Corporate Performance Director.
-- Package reason: "Avoid CPO ambiguity and define KPI/target-gap ownership."
--
-- role_id is the primary key and three foreign keys point at it with ON DELETE CASCADE and no
-- ON UPDATE, so an in-place rename would fail or orphan. The row is copied to the canonical id,
-- every child is repointed, and the original is RETIRED rather than deleted — historical
-- compatibility requires it to stay resolvable, and the rollback is then a status flip.
--
-- The physical runtime key stays 'cpo'. Renaming that too would orphan every log line, KPI row
-- and routine literal that names it, for no organizational gain: role_id is the clear name,
-- agent_key is the physical one, and both resolve.
-- ORDER IS LOAD-BEARING, AND THE REHEARSAL IS WHAT FOUND IT. org_role_one_per_agent_ux is a
-- PARTIAL unique index on runtime_agent_key WHERE status='active' — one active role per runtime
-- employee. Inserting the new row first put two active roles on 'cpo' and the migration refused
-- itself with 23505 inside the aborted rehearsal, which is exactly where that belongs. The old
-- row is retired FIRST, which drops it out of the partial index; the new row then takes the
-- physical key. A retired role holding a live employee would have been wrong anyway.
update public.org_role set status = 'retired',
  rationale = coalesce(rationale,'') || ' RETIRED by Phase A: renamed to corporate_performance_director.'
 where role_id = 'chief_performance_officer';

insert into public.org_role (role_id, display_name, primary_department_id, manager_role_id,
    runtime_mode, runtime_agent_key, responsibilities, owned_decisions, forbidden_decisions,
    activation_conditions, required_inputs, output_contracts, tools, knowledge_scopes,
    authority_level, budget_limit, handoff_targets, escalation_targets, model_policy,
    evaluation_suite, status, source_agent_keys, rationale)
  select 'corporate_performance_director', 'Corporate Performance Director', primary_department_id,
    manager_role_id, runtime_mode, runtime_agent_key, responsibilities, owned_decisions,
    forbidden_decisions, activation_conditions, required_inputs, output_contracts, tools,
    knowledge_scopes, authority_level, budget_limit, handoff_targets, escalation_targets,
    model_policy, evaluation_suite, 'active', source_agent_keys,
    'Phase A RENAME of chief_performance_officer. Package reason: avoid CPO ambiguity and define KPI/target-gap ownership. Physical runtime key cpo unchanged.'
  from public.org_role where role_id = 'chief_performance_officer';

update public.org_role_alias set role_id = 'corporate_performance_director' where role_id = 'chief_performance_officer';
update public.org_role_committee set role_id = 'corporate_performance_director' where role_id = 'chief_performance_officer';
update public.org_role set manager_role_id = 'corporate_performance_director' where manager_role_id = 'chief_performance_officer';
update public.workflow_step set actor_role = 'corporate_performance_director' where actor_role = 'chief_performance_officer';
insert into public.org_role_alias (alias, role_id, kind, reason) values
  ('chief_performance_officer', 'corporate_performance_director', 'legacy_role_id',
   'Phase A rename. Anything that still addresses the old canonical id resolves here rather than to nobody.')
  on conflict (alias) do update set role_id = excluded.role_id;

-- ============================================================================================
-- CHANGE 2 of 6 — MERGE. Partnerships Manager + Government & Enterprise Relations Manager
-- -> Strategic Partnerships & Government Relations Manager.
--
-- Both reported to business_development and both were on-demand. The package puts the merged
-- role under chief_revenue_officer, which is the change that matters: a partnership that binds
-- the company commercially should not be scoped by the person developing the pipeline.
--
-- The merged role takes the UNION of what both owned and both were forbidden, not the
-- intersection. A merge that quietly drops a forbidden decision widens authority, and that is
-- exactly the kind of silent grant this estate has been bitten by before.
-- Retired first, for the partial-index reason documented in change 1: the merged role takes
-- partnerships_mgr, and two active roles cannot hold one runtime employee. The SELECT below
-- still reads both rows — retiring changes their status, not their content.
update public.org_role set status = 'retired',
  rationale = coalesce(rationale,'') || ' RETIRED by Phase A: merged into strategic_partnerships_government_relations_manager.'
 where role_id in ('partnerships','government_relations');

insert into public.org_role (role_id, display_name, primary_department_id, manager_role_id,
    runtime_mode, runtime_agent_key, responsibilities, owned_decisions, forbidden_decisions,
    activation_conditions, required_inputs, output_contracts, tools, knowledge_scopes,
    authority_level, budget_limit, handoff_targets, escalation_targets, model_policy,
    evaluation_suite, status, source_agent_keys, rationale)
  select 'strategic_partnerships_government_relations_manager',
    'Strategic Partnerships & Government Relations Manager', 'growth', 'chief_revenue_officer',
    'on_demand_specialist', 'partnerships_mgr',
    (select string_agg(responsibilities, ' ') from public.org_role where role_id in ('partnerships','government_relations')),
    (select array_agg(distinct e) from public.org_role r, unnest(r.owned_decisions) e where r.role_id in ('partnerships','government_relations')),
    (select array_agg(distinct e) from public.org_role r, unnest(r.forbidden_decisions) e where r.role_id in ('partnerships','government_relations')),
    'Qualified strategic opportunity.',
    (select array_agg(distinct e) from public.org_role r, unnest(r.required_inputs) e where r.role_id in ('partnerships','government_relations')),
    (select array_agg(distinct e) from public.org_role r, unnest(r.output_contracts) e where r.role_id in ('partnerships','government_relations')),
    (select array_agg(distinct e) from public.org_role r, unnest(r.tools) e where r.role_id in ('partnerships','government_relations')),
    (select array_agg(distinct e) from public.org_role r, unnest(r.knowledge_scopes) e where r.role_id in ('partnerships','government_relations')),
    'execute_low', (select max(budget_limit) from public.org_role where role_id in ('partnerships','government_relations')),
    (select array_agg(distinct e) from public.org_role r, unnest(r.handoff_targets) e where r.role_id in ('partnerships','government_relations')),
    (select array_agg(distinct e) from public.org_role r, unnest(r.escalation_targets) e where r.role_id in ('partnerships','government_relations')),
    'director', 'eval_partnership_quality', 'active', array['partnerships_mgr','gov_relations_mgr'],
    'Phase A MERGE of partnerships + government_relations. Union of both mandates; forbidden decisions unioned so the merge cannot widen authority. Reports to chief_revenue_officer per the Phase A registry.';

update public.org_role_alias set role_id = 'strategic_partnerships_government_relations_manager' where role_id in ('partnerships','government_relations');
update public.org_role_committee set role_id = 'strategic_partnerships_government_relations_manager' where role_id in ('partnerships','government_relations');
update public.org_role set manager_role_id = 'strategic_partnerships_government_relations_manager' where manager_role_id in ('partnerships','government_relations');
update public.workflow_step set actor_role = 'strategic_partnerships_government_relations_manager' where actor_role in ('partnerships','government_relations');
insert into public.org_role_alias (alias, role_id, kind, reason) values
  ('partnerships','strategic_partnerships_government_relations_manager','legacy_role_id','Phase A merge.'),
  ('government_relations','strategic_partnerships_government_relations_manager','legacy_role_id','Phase A merge.')
  on conflict (alias) do update set role_id = excluded.role_id;

-- The two runtime employees become one. gov_relations_mgr is stood down; leaving it active would
-- leave an employee that no active canonical role owns, which is its own invariant failure.
update public.org_agents set active = false where agent_key = 'gov_relations_mgr';

-- ============================================================================================
-- CHANGE 3 of 6 — MOVE. Model Evaluation Reviewer: Product/Engineering/AI -> Independent
-- Assurance, Security & Reliability.
--
-- THIS IS AN INDEPENDENCE FIX, NOT A TIDY-UP. The invariant is "model/prompt creation and model
-- evaluation are separate". The reviewer sat in the same department as ai_architect and the
-- Agent & Prompt Engineer who build what it grades, reporting to the AI Director who owns their
-- output. It already held stop_authority; what it did not have was a manager with no stake in
-- the verdict. It now reports to the QA & Release Management Director.
update public.org_role set primary_department_id = 'assurance', manager_role_id = 'quality_and_release_director',
  rationale = coalesce(rationale,'') || ' Phase A MOVE to Independent Assurance: a model evaluator managed by the department that builds the models is not independent.'
 where role_id = 'model_evaluator';
update public.org_agents set department = 'assurance', manager_key = 'qa_manager' where agent_key = 'model_evaluator';

-- ============================================================================================
-- CHANGE 4 of 6 — CREATE. Product/UX Designer, the one role in the target organisation that
-- production does not have in any form.
--
-- Structure only: an org_agents row and a canonical role. No tools are granted, no knowledge
-- scope is attached, no model policy that would route spend, no cron, no route. Phase A creates
-- the accountability; anything that would make it act is Phase B and is not in this file.
insert into public.org_agents (agent_key, department, role, kind, active, title, manager_key,
    seniority, responsibilities, max_open_tasks, hired_at, available, routing_tier)
  values ('product_ux_designer', 'product_eng', 'specialist', 'brain', true, 'Product/UX Designer',
    'innovation_mgr', 'specialist', 'Own interaction flows, usability, accessibility and interface prototypes.', 5, now(), true, 'operations_specialist')
  on conflict (agent_key) do nothing;

insert into public.org_role (role_id, display_name, primary_department_id, manager_role_id,
    runtime_mode, runtime_agent_key, responsibilities, owned_decisions, forbidden_decisions,
    activation_conditions, required_inputs, output_contracts, tools, knowledge_scopes,
    authority_level, handoff_targets, escalation_targets, model_policy, evaluation_suite,
    status, source_agent_keys, rationale)
  values ('product_ux_designer', 'Product/UX Designer', 'product_eng', 'product_manager',
    'on_demand_specialist', 'product_ux_designer', 'Own interaction flows, usability, accessibility and interface prototypes.',
    array['User journey','interaction design','prototype','usability recommendation.']::text[], array['Final release approval or backend architecture.']::text[],
    'Product requirement or usability issue.', array['product requirement','usability issue']::text[],
    array['UX design/prototype and rationale.']::text[], '{}'::text[], '{}'::text[],
    'advisory', array['product_manager']::text[], array['product_manager']::text[],
    null, null, 'active', array['product_ux_designer'],
    'Phase A CREATE. Structure only: no tools, no knowledge scope, no model policy, no route, no cron.');

-- ============================================================================================
-- CHANGE 5 of 6 — RETIRE tax_overlay_uae.
--
-- Created 15 Aug 2026 at 01:21, outside this package, as a knowledge overlay for UAE tax. The
-- package answers the same need a different way and says so explicitly:
--   CURRENT_TO_FINAL_ROLE_CHANGES.csv -> "Expand scope | Financial Controller | UAE VAT/
--   corporate-tax coordination".
-- So the responsibility is not being dropped; it is being put on an accountable role instead of
-- an overlay. Three reasons this one cannot stay as it is:
--   1. the authoritative overlay registry has exactly 86 entries and this is not one of them;
--   2. the invariants require every overlay to declare an operational owner, an invocation role
--      and a knowledge-governance path — this row declares none of the three;
--   3. four checks in scripts/checks counted overlay ROLES and compared the total to the 86
--      CATEGORY overlays, so this row made them fail. That is the instrument being imprecise,
--      and the instrument is corrected in the same commit — but the row is still not in the
--      target organisation.
-- Retired, not deleted, and the rollback is a status flip.
update public.org_role set status = 'retired',
  rationale = coalesce(rationale,'') || ' RETIRED by Phase A: not in the 86-entry category overlay registry and declaring none of the governance fields an overlay must have. UAE VAT/corporate-tax coordination sits with the Financial Controller per CURRENT_TO_FINAL_ROLE_CHANGES.csv.'
 where role_id = 'tax_overlay_uae';

-- AND IT RESOLVES TO THE ROLE THAT NOW CARRIES THE WORK, which the postcondition below insisted
-- on: a retired role with no alias resolves to nobody, and anything still addressing UAE tax
-- would have gone nowhere silently. The alias is not cosmetic — it is the difference between
-- "this moved to the Financial Controller" and "this vanished".
insert into public.org_role_alias (alias, role_id, kind, reason) values
  ('tax_overlay_uae', 'financial_controller', 'legacy_role_id',
   'Phase A: UAE VAT and corporate-tax coordination is an expanded Financial Controller scope, not a standing overlay.')
  on conflict (alias) do update set role_id = excluded.role_id;

