-- ============================================================================================
-- POSTCONDITIONS. Every one of these is an invariant from PHASE_A_INVARIANTS.md. Any failure
-- raises, and the raise takes the whole migration with it.
-- ============================================================================================
do $$
declare v int; v_txt text;
begin
  select count(*) into v from public.org_departments where active;
  if v <> 10 then raise exception 'POST: active primary departments = %, expected 10', v; end if;

  select count(*) into v from public.org_role where status='active' and runtime_mode <> 'knowledge_overlay';
  if v <> 90 then raise exception 'POST: canonical accountable standing roles = %, expected 90', v; end if;

  select count(*) into v from public.org_role where status='active' and runtime_mode = 'knowledge_overlay';
  if v <> 86 then raise exception 'POST: category overlays = %, expected 86', v; end if;

  select count(*) into v from public.org_role where status='active' and runtime_mode='knowledge_overlay'
    and role_id !~ '^category_overlay_[0-9]{3}_';
  if v <> 0 then raise exception 'POST: % overlay(s) are not category overlays', v; end if;

  -- the 4,17,11,11,11,7,7,7,9,6 shape, asserted as a sorted multiset so it does not depend on
  -- which department key carries which count.
  select string_agg(n::text, ',' order by n) into v_txt from (
    select count(*) n from public.org_role where status='active' and runtime_mode <> 'knowledge_overlay'
     group by primary_department_id) s;
  if v_txt <> '4,6,7,7,7,9,11,11,11,17'
    then raise exception 'POST: roles per department = %, expected 4,6,7,7,7,9,11,11,11,17', v_txt; end if;

  select count(*) into v from public.org_role where status='active' and manager_role_id = role_id;
  if v <> 0 then raise exception 'POST: % role(s) manage themselves', v; end if;

  -- reporting cycles, walked rather than assumed. The a10_org_role_no_cycle trigger refuses new
  -- ones; this proves none survived the repointing above.
  with recursive up(role_id, mgr, depth, path) as (
    select role_id, manager_role_id, 1, array[role_id] from public.org_role where status='active'
    union all
    select u.role_id, r.manager_role_id, u.depth+1, u.path || r.role_id
      from up u join public.org_role r on r.role_id = u.mgr and r.status='active'
     where u.depth < 30 and not r.role_id = any(u.path))
  select count(*) into v from up where depth >= 30;
  if v <> 0 then raise exception 'POST: % reporting chain(s) do not terminate', v; end if;

  select count(*) into v from public.org_role where status='active' and necessity_status is null;
  if v <> 0 then raise exception 'POST: % active role(s) have no necessity status', v; end if;

  select count(*) into v from public.org_role where status='active' and runtime_mode <> 'knowledge_overlay'
    and (forbidden_decisions is null or cardinality(forbidden_decisions) = 0);
  if v <> 0 then raise exception 'POST: % accountable role(s) have no forbidden decisions', v; end if;

  select count(*) into v from public.org_workflow_ownership;
  if v <> 30 then raise exception 'POST: organizational workflows = %, expected 30', v; end if;

  select count(*) into v from public.org_workflow_ownership o
   where not exists (select 1 from public.org_role r where r.role_id = o.accountable_role_id and r.status='active');
  if v <> 0 then raise exception 'POST: % workflow(s) are owned by a role that is not an active canonical role', v; end if;

  select count(*) into v from public.org_workflow_ownership where independent_reviewer = accountable_role_id;
  if v <> 0 then raise exception 'POST: % workflow(s) have the owner as their own reviewer', v; end if;

  -- an active employee that no active canonical role owns can act while being accountable to
  -- nobody. This is what stood gov_relations_mgr down above.
  select count(*) into v from public.org_agents a where a.active
    and not exists (select 1 from public.org_role r where r.runtime_agent_key = a.agent_key and r.status='active');
  if v <> 0 then raise exception 'POST: % active employee(s) map to no active canonical role', v; end if;

  -- two active roles sharing one runtime employee is a duplicate identity.
  select count(*) into v from (select runtime_agent_key from public.org_role
     where status='active' and runtime_agent_key is not null group by 1 having count(*) > 1) d;
  if v <> 0 then raise exception 'POST: % runtime employee(s) are held by two active roles', v; end if;

  -- every retired role stays resolvable. Historical compatibility is an invariant, not a courtesy.
  select string_agg(role_id, ', ') into v_txt from public.org_role r where r.status = 'retired'
    and not exists (select 1 from public.org_role_alias a where a.alias = r.role_id);
  if v_txt is not null then raise exception 'POST: retired role(s) resolve to nobody: %', v_txt; end if;

  -- the independence fix actually landed.
  select count(*) into v from public.org_role where role_id='model_evaluator'
    and primary_department_id='assurance' and manager_role_id='quality_and_release_director' and status='active';
  if v <> 1 then raise exception 'POST: the model evaluator is not independently managed'; end if;

  raise notice 'PHASE A POSTCONDITIONS PASSED: 10 departments, 90 roles, 86 overlays, 30 owned workflows.';
end $$;
